    sc_0638: "Enter the team size.",
    sc_0639: "Players enter individually. After each round before the playoff, a new round is created with the closest opponents by current ELO who have not played each other yet.",
    sc_0640: "In the playoffs, players with the closest ELO are paired as well.",
    sc_0641: "Each player has 1 joker. One match a week is required. A match that uses a joker gets +7 days; if it still does not finish, the player who used the joker loses by default.",
    sc_0642: "If both players use a joker for the same match, or they do it mutually, the time extends by +7 once, not +7 +7; because both did it mutually, the jokers are not used up.",
    sc_0643: "When players with the same points reach the playoff, the one with the higher average (games won / games played) is taken first.",
    sc_0644: "If players on the playoff cutoff are tied on points, average, set ratio and game ratio, one more round is added before a draw; the tied players are paired with the closest opponents they have not played. This repeats until the tie breaks; a draw is used only when no suitable pairing remains.",
    sc_0645: "📋 Doubles competitive rules",
    sc_0646: "Players can enter as a pair (a team) or apply individually — individual applicants are paired at the start with the closest ELO. The single player left with the lowest ELO cannot enter.",
    sc_0647: "In mixed tournaments, the system does not pair two women from the individual entrants on the same team.",
    sc_0648: "Each team has 1 joker. One match a week is required; if the joker is used, the team gets +7 days. The team that used the joker must make the concessions needed to finish the match in that time; if they do not, that team loses by default.",
    sc_0649: "If the opponent of the team that used the joker also plays a mutual joker for the same match, the joker is not used up; the 7 days are added only once (weather, no court available, and similar cases).",
    sc_0650: "Team ELO averages are used. For as many matches as were chosen before the playoff, each team meets every other team at most once, starting each round with the closest average.",
    sc_0651: "If teams are tied on points in the table before the playoff, the average (games played ratio) is used.",
    sc_0652: "When a team wins or loses, both players gain or lose ELO individually — the amount uses the same points table as other competitive matches, based on the difference of the two teams' average ELO.",
    sc_0653: "If teams on the playoff cutoff are tied on points, average, set ratio and game ratio, one more round is added before a draw; the tied teams are paired with the closest average-ELO opponents they have not played. This repeats until the tie breaks; a draw is only a last resort when no suitable pairing remains.",
    sc_0654: "📋 Singles practice rules",
    sc_0655: "Players enter individually.",
    sc_0656: "When the draw is made, each round pairs random players, and it is known who plays whom until the playoffs.",
    sc_0657: "If both sides are free, players may contact each other and finish their matches earlier.",
    sc_0658: "📋 Doubles practice rules",
    sc_0659: "Players can enter as a pair (a team) or apply individually — individual applicants are paired at random when the tournament starts. A player with no partner cannot enter.",
    sc_0660: "Each team has 1 joker. One match a week is required; if the joker is used, the team gets +7 days. The team that used the joker must make the concessions needed to finish the match in that time; if they do not, that team loses by default.",
    sc_0661: "When the draw is made, each round pairs random teams, and it is known which team plays which until the playoffs.",
    sc_0662: "When teams with the same points reach the playoff, the one with the higher average (games won / games played) is taken first.",
    sc_0663: "If both sides are free, teams may contact each other and finish their matches earlier.",
    sc_0664: "Players enter individually. The first round is paired by ELO closeness; later rounds use the current points (and average) — similar ranks meet.",
    sc_0665: "The same two players are not paired more than once if it can be avoided. If there is an odd player, the lowest-ranked one who has not had a bye yet gets the bye; a bye counts as +3 points / +1 win.",
    sc_0666: "The number of rounds is the organizer's choice; if left empty, about log₂(player count) rounds are played. There is no playoff — the ranking comes from the final table.",
    sc_0667: "Ranking: points → average (games won / games played) → set ratio → game ratio → fixed draw.",
    sc_0668: "If both players use a joker for the same match, or they do it mutually, the time extends by +7 once, not +7 +7; because it is mutual, the jokers are not used up.",
    sc_0669: "Matches are competitive; a win or loss changes ELO. Use the comment section on the match card to agree; the score is confirmed by both sides.",
    sc_0670: "Players enter individually. At least 4 players are required. The draw follows the ELO ranking; missing spots are filled with byes.",
    sc_0671: "There is a winners bracket and a losers bracket. One loss drops you to the lower bracket; two losses eliminate you.",
    sc_0672: "The winners-bracket champion meets the losers-bracket champion in the grand final. If the losers-bracket champion wins, a reset (second) grand final is played.",
    sc_0673: "Matches are competitive; a win or loss changes ELO. The score is confirmed by both sides.",
    sc_0674: "There is no league round before the playoff — the whole tournament is knockout.",
    sc_0675: "Players enter individually (no fixed partner). At least 4 players are required. Each round forms temporary 2v2 pairs; the partner changes every round.",
    sc_0676: "The same person is not a partner again, and the same opponents are not faced again, as far as possible. If the player count is not a multiple of 4, those who sit out rotate between rounds.",
    sc_0677: "The ranking is individual: each player banks the games their team won that round as points. There is no playoff — the highest points finish first.",
    sc_0678: "The number of rounds is the organizer's choice; if left empty, it is set automatically from the player count (maximum 7).",
    sc_0679: "Each player has 1 joker. One match a week is required. A match that uses a joker gets +7 days; if it still does not finish, the side that used the joker loses by default.",
    sc_0680: "If a mutual joker is played, the time extends by +7 once; the jokers are not used up.",
