    sc_0721: "Team average",
    sc_0722: "In competitive matches the point change is calculated by comparing ",
    sc_0723: "the two teams' average ratings",
    sc_0724: " (you can see it next to each player on the roster card and next to the team title). The table on the Dominant/Competitive tabs below is read from the ",
    sc_0725: "gap",
