    sc_0739: "🎯 Rating calibration protection",
    sc_0740: "In volleyball this protection is ",
    sc_0741: "team-based",
    sc_0742: " and is checked every match (it is not limited to the first 3 matches after the survey, as in tennis/padel):",
    sc_0743: "After a player ",
    sc_0744: "the rating survey",
    sc_0745: " finishes, in the ",
    sc_0746: "first 3 matches",
