    sc_0749: "If the winning team's average is ",
    sc_0750: "1 point or more below the losing team's",
    sc_0751: " (for example 0.20 against 1.30), the system treats the result as suspicious — the survey may have been answered wrong, or a player of the wrong level was added.",
    sc_0752: "If the player, alone and/or as a team, wins by ",
    sc_0753: "a gap of 1 point or more from the average rating",
    sc_0754: ", the system decides that this match's rating was calculated wrong.",
    sc_0755: "Points do not count",
    sc_0756: "In that case, from the match result, ",
    sc_0757: "no points gained or lost are applied.",
