    sc_0763: " and is asked to complete it again.",
    sc_0764: "💡 Why is it like this?",
    sc_0765: "Survey answers may not fully reflect a player's real level. This protection stops players who start with the wrong rating from affecting their opponents, and it keeps competition fair for everyone.",
    sc_0766: "No fixed table, a continuously updated average",
    sc_0767: "Your rating is not taken from a fixed points table like the old system. It is ",
    sc_0768: "the weighted average of at most 30 matches in the last 12 months",
    sc_0769: " and it is recalculated continuously. So it is shaped by your current form, not by a single match.",
    sc_0770: "Match performance score",
    sc_0771: "Each match becomes a score that reflects how you played against that opponent. The ",
    sc_0772: "more one-sided the score",
