    sc_0775: "Recent ",
    sc_0776: "matches weigh more — a match older than 12 months counts as zero.",
    sc_0777: "Long matches such as 3 sets ",
    sc_0778: "count more than a one-set match.",
    sc_0779: "A result against an opponent who has played few matches ",
    sc_0780: "(whose reliability is still low) counts less.",
    sc_0781: "Singles and doubles are scored separately",
    sc_0782: "Singles and doubles ratings are calculated and shown completely separately — being good at singles does not directly change your doubles rating, and being good at doubles does not directly change your singles rating.",
