    sc_0492: "🃏 Karşılıklı Joker",
    sc_0493: "Rakibiniz \"maç yarıda kaldı\" diyerek süreyi zaten 7 gün uzattı. Onaylarsanız karşılıklı sayılır — süre tekrar uzamaz ama iki tarafın da ek süre hakkı tükenmez. Emin misiniz?",
