    sc_0723: "iki takımın ortalama derece puanı",
    sc_0724: "karşılaştırılarak hesaplanır (kadro kartında her oyuncunun yanında ve takım başlığının yanında görebilirsin). Aşağıdaki Dominant/Rekabetçi sekmelerindeki tablo, bu iki ortalama arasındaki",
    sc_0725: "farka",
