    sc_0727: "Takım Bazlı Kalibrasyon Koruması",
    sc_0728: "Kazanan takımın ortalama derece puanı, kaybeden takımınkinden",
    sc_0729: "1.0 puan veya daha fazla düşükse",
    sc_0730: "(ör. kazanan takım ortalaması 0.20, kaybeden 1.30), bu sonuç şüpheli kabul edilir — muhtemelen anket yanlış cevaplanmış ya da kadroya seviyesi uygun olmayan bir oyuncu eklenmiştir.",
    sc_0731: "Bu durumda",
    sc_0732: "kazanan takımın hiçbiri puan kazanmaz",
    sc_0733: "(voleybolde bu, tenis/padel'den farklı olarak sadece yeni ankete girenlerle sınırlı değil, TÜM kazanan takıma uygulanır) ve herkes derecelendirme anketine tekrar yönlendirilir.",
    sc_0734: "Antrenman vs Rekabetçi",
    sc_0735: "Antrenman",
    sc_0736: "modundaki maçlarda derece puanı değişmez, uygulamada kayıtlı olmayan oyuncular da kadroya eklenebilir.",
    sc_0737: "Rekabetçi",
    sc_0738: "modda ise sadece uygulamaya kayıtlı (derece puanı olan) oyuncular kadroya eklenebilir, maç sonunda puan kazanılır/kaybedilir.",
    sc_0739: "🎯 Derece Kalibrasyon Koruması",
    sc_0740: "Voleybolde bu koruma",
    sc_0741: "takım bazında",
    sc_0742: ", her maçta değerlendirilir (tenis/padel'deki gibi sadece anketten sonraki ilk 3 maçla sınırlı değildir):",
    sc_0743: "Bir oyuncu",
    sc_0744: "derecelendirme anketini",
    sc_0745: "tamamladıktan sonra rekabetçi modda oynadığı",
    sc_0746: "ilk 3 maçta",
    sc_0747: "şu koşul değerlendirilir:",
    sc_0748: "Tetikleyici Koşul",
    sc_0749: "Kazanan takımın ortalaması, kaybeden takımınkinden",
    sc_0750: "1 puan veya daha fazla düşükse",
    sc_0751: "(ör. 0.20'ye karşı 1.30) sistem bu sonucu şüpheli kabul eder — anket yanlış cevaplanmış ya da kadroya seviyesi uygun olmayan bir oyuncu eklenmiş olabilir.",
    sc_0752: "Oyuncu bireysel ve/veya takım olarak",
    sc_0753: "ortalama derece puanından 1 puan veya daha fazla fark",
    sc_0754: "ile kazanıyorsa sistem bu maçın derecesinin yanlış hesaplandığını tespit eder.",
    sc_0755: "Puan Sayılmaz",
    sc_0756: "Bu durumda maç sonucundan",
    sc_0757: "kazanılan/kaybedilen hiçbir puan uygulanmaz.",
    sc_0758: "Oyuncu ve rakip için derece puanları değişmez.",
    sc_0759: "Ankete Yönlendirme",
    sc_0760: "Kazanan takımın tamamı",
    sc_0761: "doğru derece puanlaması yapılabilmesi için",
    sc_0762: "otomatik olarak derecelendirme anketine yönlendirilir",
    sc_0763: "ve anketi yeniden tamamlaması istenir.",
    sc_0764: "💡 Neden böyle?",
    sc_0765: "Anket cevapları oyuncunun gerçek seviyesini her zaman tam yansıtmayabilir. Bu koruma sistemi, yanlış derece ile başlayan oyuncuların rakiplerini etkilemesini önler ve tüm oyuncular için adil bir rekabet ortamı sağlar.",
    sc_0766: "Sabit Tablo Yok, Sürekli Güncellenen Ortalama",
    sc_0767: "Derece puanın, eski sistemdeki gibi sabit bir puan tablosuna göre değil,",
    sc_0768: "son 12 ay içindeki en fazla 30 maçının ağırlıklı ortalamasına",
    sc_0769: "göre sürekli yeniden hesaplanır. Yani puanın tek bir maçla değil, güncel performansınla şekillenir.",
    sc_0770: "Maç Performans Puanı",
    sc_0771: "Her maç, rakibine göre sergilediğin performansı yansıtan bir puana çevrilir. Rakibini",
    sc_0772: "ne kadar farklı skorla",
    sc_0773: "(ör. 6-1, 6-0) yenersen, o maçtaki performans puanın o kadar yüksek çıkar. Yakın skorla kazanmak (7-6, 6-4) ya da kaybetmek, performansını rakibinin puanına daha yakın tutar.",
    sc_0774: "Her Maç Aynı Ağırlıkta Değil",
    sc_0775: "Yakın zamanda",
    sc_0776: "oynanan maçlar daha ağır basar — 12 aydan eski bir maçın etkisi tamamen sıfırlanır.",
    sc_0777: "3 set gibi uzun",
    sc_0778: "süren maçlar, tek setlik bir maça göre daha belirleyicidir.",
    sc_0779: "Az maç oynamış",
    sc_0780: "(güvenilirliği henüz düşük) bir rakibe karşı alınan sonucun etkisi azaltılır.",
    sc_0781: "Tekli / Çiftler Ayrı Puanlanır",
    sc_0782: "Tekli ve çiftler maçlarının derece puanı tamamen ayrı hesaplanır ve gösterilir — tekilerde iyi olman çiftler puanını, çiftlerde iyi olman da tekiler puanını doğrudan etkilemez.",
    sc_0783: "Sabit \"+X / -Y\" Tablosu Yok",
