    sc_0617: (a) => `🤖 Демо (${a}/40)`,
    sc_0618: "🏆 Создание турнира",
    sc_0619: "Вам разрешено создавать турниры",
    sc_0620: "Поскольку вы подтверждённый тренер, право выдано автоматически — турнир можно создать без одобрения админа.",
    sc_0621: "Вы можете создать турнир, потому что подписка заведения активна.",
