    sc_0492: "🃏 Gegenseitiger Joker",
    sc_0493: "Ihr Gegner hat die Zeit bereits um 7 Tage verlängert, weil das Spiel abgebrochen wurde. Wenn Sie bestätigen, gilt es als gegenseitig — die Zeit wird nicht noch einmal verlängert, aber das Extra-Zeit-Recht verfällt auf keiner Seite. Sind Sie sicher?",
    sc_0494: "Das Spiel wirklich als abgebrochen markieren und Extra-Zeit anfordern? Die Zeit wird um 7 Tage verlängert und Ihr Extra-Zeit-Recht ist verbraucht.",
    sc_0495: "Ihr Gegner hat die Zeit bereits mit einem Joker um 7 Tage verlängert. Wenn Sie bestätigen, gilt es als gegenseitig — die Zeit wird nicht noch einmal verlängert, aber der Joker verfällt auf keiner Seite. Sind Sie sicher?",
    sc_0496: "Den Joker für dieses Spiel wirklich einsetzen? Die Zeit wird um 7 Tage verlängert und Ihr Joker ist verbraucht.",
