    sc_0694: "⏰ Späteste Spielzeit",
    sc_0695: "🏐 Volleyballregeln & Punkte",
    sc_0696: "📊 So funktioniert die Wertung",
    sc_0697: "📊 Punkte im Wettkampfspiel",
    sc_0698: "Punkte richten sich nach dem ",
    sc_0699: " zwischen den Spielern und nach dem Spieltyp.",
    sc_0700: "Grün",
    sc_0701: " = gewonnene Punkte  ·",
    sc_0702: "Rot",
    sc_0703: " = verlorene Punkte",
    sc_0704: " (in Teamspielen wird das aus dem Wertungsschnitt der beiden Teams berechnet.)",
    sc_0705: "📋 Regeln",
    sc_0706: "📈 System",
    sc_0707: "⚖️ Punkte",
    sc_0708: "🏆 Dominant",
    sc_0709: "⚔️ Wettkampf",
    sc_0710: "🎯 Kalibrierung",
    sc_0711: "Strafe bei Nichterscheinen",
    sc_0712: "Ein Spieler, der zum Spiel ",
    sc_0713: "ohne Entschuldigung fehlt,",
    sc_0714: " kann von den anderen Teilnehmern gemeldet werden. Wenn ein Admin die Meldung freigibt:",
    sc_0715: "• Von der Wertung werden ",
    sc_0716: "0,20 Punkte",
    sc_0717: " abgezogen.",
    sc_0718: "• Weil keine Entschuldigung vorlag, ",
    sc_0719: "eine Sperre für ein neues Spiel über 3 Spiele",
    sc_0720: " kann gelten.",
    sc_0721: "Teamschnitt",
    sc_0722: "In Wettkampfspielen wird die Punkteänderung durch den Vergleich ",
    sc_0723: "des Wertungsschnitts der beiden Teams",
    sc_0724: " (sichtbar neben jedem Spieler auf der Kaderkarte und neben dem Teamtitel). Die Tabelle auf den Tabs Dominant/Wettkampf unten liest man am ",
    sc_0725: "Abstand",
    sc_0726: " zwischen diesen beiden Schnitten ab.",
    sc_0727: "Kalibrierungsschutz auf Teamebene",
    sc_0728: "Wenn der Wertungsschnitt des Siegerteams ",
    sc_0729: "1,0 Punkte oder mehr unter dem des Verliererteams liegt",
    sc_0730: " (zum Beispiel Sieger-Schnitt 0,20, Verlierer 1,30), gilt das Ergebnis als verdächtig — der Fragebogen wurde wahrscheinlich falsch beantwortet oder ein Spieler mit unpassendem Niveau wurde aufgenommen.",
    sc_0731: "In diesem Fall ",
    sc_0732: "erhält niemand im Siegerteam Punkte",
    sc_0733: " (im Volleyball gilt das, anders als bei Tennis/Padel, nicht nur für neue Fragebogen, sondern für das GANZE Siegerteam), und alle werden erneut zum Bewertungsfragebogen geschickt.",
    sc_0734: "Training und Wettkampf",
    sc_0735: "Training",
    sc_0736: "-Spiele ändern die Wertung nicht, und Spieler, die nicht in der App registriert sind, können in den Kader.",
    sc_0737: "Wettkampf",
    sc_0738: "-Modus lässt nur registrierte Spieler (mit Wertung) in den Kader, und am Spielende werden Punkte gewonnen oder verloren.",
    sc_0739: "🎯 Schutz der Wertungskalibrierung",
    sc_0740: "Im Volleyball wird dieser Schutz ",
    sc_0741: "auf Teamebene",
    sc_0742: " in jedem Spiel geprüft (nicht nur in den ersten 3 Spielen nach dem Fragebogen wie bei Tennis/Padel):",
    sc_0743: "Nachdem ein Spieler ",
    sc_0744: "den Bewertungsfragebogen",
    sc_0745: " ausgefüllt hat, wird in den ",
    sc_0746: "ersten 3 Spielen",
    sc_0747: " im Wettkampfmodus diese Bedingung geprüft:",
    sc_0748: "Auslöser",
    sc_0749: "Wenn der Schnitt des Siegerteams ",
    sc_0750: "1 Punkt oder mehr unter dem des Verliererteams liegt",
    sc_0751: " (zum Beispiel 0,20 gegen 1,30) hält das System das Ergebnis für verdächtig — der Fragebogen kann falsch beantwortet oder ein Spieler mit unpassendem Niveau hinzugefügt worden sein.",
    sc_0752: "Wenn der Spieler allein und/oder im Team mit ",
    sc_0753: "einem Abstand von 1 Punkt oder mehr zum Wertungsschnitt",
    sc_0754: " gewinnt, erkennt das System, dass die Wertung dieses Spiels falsch berechnet wurde.",
    sc_0755: "Punkte zählen nicht",
    sc_0756: "In diesem Fall werden aus dem Spielergebnis ",
    sc_0757: "keine gewonnenen oder verlorenen Punkte angewandt.",
    sc_0758: "Die Wertung von Spieler und Gegner ändert sich nicht.",
    sc_0759: "Zum Fragebogen",
    sc_0760: "Das ganze Siegerteam ",
    sc_0761: "damit die Wertung stimmt, ",
    sc_0762: "wird automatisch zum Bewertungsfragebogen geschickt",
    sc_0763: " und gebeten, ihn erneut auszufüllen.",
    sc_0764: "💡 Warum ist das so?",
    sc_0765: "Fragebogen-Antworten spiegeln das echte Niveau nicht immer genau. Dieser Schutz verhindert, dass Spieler mit falscher Startwertung ihre Gegner beeinflussen, und hält den Wettkampf für alle fair.",
    sc_0766: "Keine feste Tabelle, ein ständig aktualisierter Schnitt",
    sc_0767: "Ihre Wertung kommt nicht aus einer festen Punktetabelle wie im alten System, sondern ",
    sc_0768: "der gewichtete Schnitt von höchstens 30 Spielen der letzten 12 Monate",
    sc_0769: " und wird ständig neu berechnet. Geformt wird sie von der aktuellen Form, nicht von einem einzelnen Spiel.",
    sc_0770: "Spiel-Leistungspunkte",
    sc_0771: "Jedes Spiel wird zu einer Punktzahl dafür, wie Sie gegen diesen Gegner gespielt haben. Je ",
    sc_0772: "deutlicher das Ergebnis",
    sc_0773: " (zum Beispiel 6:1, 6:0), desto höher die Leistungspunkte dieses Spiels. Ein knapper Sieg (7:6, 6:4) oder eine Niederlage hält die Leistung näher an der Wertung des Gegners.",
    sc_0774: "Nicht jedes Spiel wiegt gleich",
    sc_0775: "Jüngere ",
    sc_0776: "Spiele wiegen mehr — ein Spiel, das älter als 12 Monate ist, zählt null.",
    sc_0777: "Lange Spiele wie über 3 Sätze ",
    sc_0778: "zählen mehr als ein Spiel über einen Satz.",
    sc_0779: "Ein Ergebnis gegen einen Gegner mit wenigen Spielen ",
    sc_0780: "(dessen Zuverlässigkeit noch gering ist) zählt weniger.",
    sc_0781: "Einzel und Doppel werden getrennt gewertet",
    sc_0782: "Einzel- und Doppelwertung werden völlig getrennt berechnet und angezeigt — stark im Einzel ändert die Doppelwertung nicht direkt, und umgekehrt.",
    sc_0783: "Keine feste Tabelle „+X / −Y“",
    sc_0784: "Wie viele Punkte Sie bei einem Sieg gewinnen oder bei einer Niederlage verlieren, ist nicht fest — es hängt von den Faktoren unten ab.",
    sc_0785: "Wenn Sie einen stärkeren Gegner schlagen",
    sc_0786: "Einen Gegner zu schlagen, ",
    sc_0787: "der eine höhere Wertung hat als Sie",
    sc_0788: " ist ein besseres Ergebnis als erwartet, daher steigt die Wertung deutlich. Je deutlicher das Ergebnis (zum Beispiel 6:1, 6:2), desto größer die Wirkung.",
    sc_0789: "Wenn Sie gegen einen schwächeren Gegner verlieren",
    sc_0790: "Eine Niederlage gegen einen Gegner mit niedrigerer Wertung",
    sc_0791: " ist ebenfalls unerwartet, daher sinkt die Wertung deutlich.",
    sc_0792: "Erwartete Ergebnisse ändern wenig",
    sc_0793: "Gegen einen Gegner auf ähnlichem Niveau ändert ein vorhersehbares oder knappes Ergebnis (Sieg oder Niederlage) die Wertung nur wenig.",
    sc_0794: "Überraschende Ergebnisse ",
    sc_0795: "ändern die Wertung viel stärker.",
    sc_0796: "💡 Ein Spiel ändert nicht alles",
    sc_0797: "Weil die Wertung der Schnitt der letzten 30 Spiele ist, verschiebt ein Ergebnis sie nicht plötzlich stark — mit der Zeit spiegelt sie den Verlauf Ihrer Spiele.",
